import requests, numpy as np, pandas as pd, matplotlib.pyplot as plt, json
E="https://rest.ensembl.org"
def ens(p):
    r=requests.get(E+p,headers={"Content-Type":"application/json"},timeout=240); r.raise_for_status(); return r.json()
def regions(lst):
    out=[]
    for i in range(0,len(lst),45):
        r=requests.post(E+"/sequence/region/human",headers={"Content-Type":"application/json","Accept":"application/json"},
                        data=json.dumps({"regions":lst[i:i+45]}),timeout=300)
        r.raise_for_status(); out+=r.json()
    return [x["seq"].upper() for x in out]

# ---- collect real human internal exons from a 4 Mb window to build empirical splice-site PWMs ----
ex=ens("/overlap/region/human/10:82000000-86000000?feature=exon")
by_tr={}
for e in ex:
    by_tr.setdefault(e["Parent"],[]).append(e)
don_reg=[]; acc_reg=[]
for tr,exons in by_tr.items():
    if len(exons)<3: continue
    st=exons[0]["strand"]
    exons=sorted(exons,key=lambda x:x["start"], reverse=(st==-1))
    for e in exons[:-1]:                      # every exon with a downstream intron -> donor
        if st==1: s=e["end"]-2; don_reg.append(f"10:{s}..{s+8}:1")
        else:     s=e["start"]-6; don_reg.append(f"10:{s}..{s+8}:-1")
    for e in exons[1:]:                       # every exon with an upstream intron -> acceptor
        if st==1: s=e["start"]-20; acc_reg.append(f"10:{s}..{s+22}:1")
        else:     s=e["end"]-2;    acc_reg.append(f"10:{s}..{s+22}:-1")
don_reg=list(dict.fromkeys(don_reg))[:900]; acc_reg=list(dict.fromkeys(acc_reg))[:900]
print("candidate donor sites:",len(don_reg)," acceptor sites:",len(acc_reg))
D=[s for s in regions(don_reg) if len(s)==9 and s[3:5]=="GT"]
A=[s for s in regions(acc_reg) if len(s)==23 and s[18:20]=="AG"]
print("real donors with GT:",len(D)," real acceptors with AG:",len(A))

def pwm(seqs,L):
    m=np.zeros((4,L)); idx={'A':0,'C':1,'G':2,'T':3}
    for s in seqs:
        for i,c in enumerate(s):
            if c in idx: m[idx[c],i]+=1
    m=(m+0.5)/(m.sum(0)+2.0)
    return m
PD=pwm(D,9); PA=pwm(A,23)
bg=np.array([0.25]*4)
def score(seq,P):
    idx={'A':0,'C':1,'G':2,'T':3}
    return float(sum(np.log2(P[idx[c],i]/0.25) for i,c in enumerate(seq) if c in idx))
Dsc=np.array([score(s,PD) for s in D]); Asc=np.array([score(s,PA) for s in A])
print("background donor score: mean %.2f sd %.2f | acceptor: mean %.2f sd %.2f"%(Dsc.mean(),Dsc.std(),Asc.mean(),Asc.std()))

# ---- LRIT2 sites of interest (minus strand gene) ----
sites={
 "micro-exon DONOR (iso2-specific)":      ("donor",   "10:84222822..84222830:-1"),
 "micro-exon ACCEPTOR (iso2-specific)":   ("acceptor","10:84222855..84222877:-1"),
 "constitutive exon 2 DONOR":             ("donor",   "10:84224330..84224338:-1"),
 "constitutive exon 3 ACCEPTOR":          ("acceptor","10:84222678..84222700:-1"),
 "constitutive exon 1 DONOR":             ("donor",   "10:84225408..84225416:-1"),
 "constitutive exon 2 ACCEPTOR":          ("acceptor","10:84225112..84225134:-1"),
}
seqs=regions([v[1] for v in sites.values()])
res=[]
for (nm,(kind,reg)),sq in zip(sites.items(),seqs):
    if kind=="donor":
        ok = sq[3:5]=="GT"; sc=score(sq,PD); pct=100*(Dsc<sc).mean(); z=(sc-Dsc.mean())/Dsc.std()
    else:
        ok = sq[18:20]=="AG"; sc=score(sq,PA); pct=100*(Asc<sc).mean(); z=(sc-Asc.mean())/Asc.std()
    res.append(dict(site=nm,kind=kind,sequence=sq,canonical_dinuc=ok,score_bits=round(sc,2),
                    percentile_vs_real_sites=round(pct,1),z=round(z,2)))
df=pd.DataFrame(res)
print("\n"+df.to_string(index=False))
df.to_csv("out_splice_scores.csv",index=False)

fig,axes=plt.subplots(1,2,figsize=(12.5,4.4))
for ax,bgs,kind,lab in [(axes[0],Dsc,"donor","5' donor"),(axes[1],Asc,"acceptor","3' acceptor")]:
    ax.hist(bgs,bins=40,color="#cccccc",edgecolor="white")
    sub=df[df.kind==kind]
    cols={"micro":"crimson"}
    for _,r in sub.iterrows():
        c="crimson" if "micro" in r.site else "steelblue"
        ax.axvline(r.score_bits,color=c,lw=2)
        ax.text(r.score_bits,ax.get_ylim()[1]*(0.95 if "micro" in r.site else 0.75),
                f" {r.site.split(' ')[0]} {r.site.split(' ')[1]}\n {r.percentile_vs_real_sites:.0f}th pct",
                color=c,fontsize=7.5,rotation=0,va="top")
    ax.set_xlabel(f"{lab} PWM score (bits)"); ax.set_ylabel("real chr10 splice sites")
    ax.set_title(f"{lab} strength: LRIT2 sites against {len(bgs)} real chr10 sites",fontsize=10)
plt.suptitle("The isoform 2 micro-exon has unremarkable splice sites, so inclusion is not blocked by site strength",fontsize=11)
plt.tight_layout(); plt.show()
